#!/bin/sh
# Stubs (concert history) installer for Alpine Linux (OpenRC). Generated by installer/build.sh: the app is the
# base64 tarball after the __PAYLOAD_BELOW__ line at the end of this file.
# Re-runnable: replaces /opt/stubs, keeps /var/lib/stubs (database and images) and /etc/conf.d/stubs, and only adds
# settings that are missing from the config.
#
#   sh setup-stubs.sh                       install / upgrade
#   STUBS_PORT=8774 sh setup-stubs.sh       first install on another port (an existing install keeps its PORT)
#   sh setup-stubs.sh --uninstall           remove app, service and backup job (keeps data, config and backups)
set -eu

NAME=stubs
APP_DIR=/opt/stubs
DATA_DIR=/var/lib/stubs
BACKUP_DIR=/var/backups/stubs
CONF=/etc/conf.d/stubs
INITD=/etc/init.d/stubs
LOG=/var/log/stubs.log
SVC_USER=stubs
BACKUP_JOB=/etc/periodic/daily/stubs-backup
OPS_CONF="${OPS_CONF:-/etc/conf.d/ops}"
PORT="${STUBS_PORT:-8773}"

UNINSTALL=
case "${1:-}" in
  "") ;;
  --uninstall) UNINSTALL=1 ;;
  *) echo "Unknown argument: $1 (use --uninstall)."; exit 1 ;;
esac

[ "$(id -u)" = 0 ] || { echo "Run as root."; exit 1; }
command -v apk >/dev/null || { echo "This installer is for Alpine (apk)."; exit 1; }

if [ -n "$UNINSTALL" ]; then
  rc-service "$NAME" stop >/dev/null 2>&1 || true
  rc-update del "$NAME" default >/dev/null 2>&1 || true
  rm -f "$INITD" "$BACKUP_JOB"
  rm -rf "$APP_DIR"
  echo "Removed the app, the service and the backup job. Kept $DATA_DIR, $CONF and $BACKUP_DIR."
  exit 0
fi

conf_val() { sed -n "s/^$1=//p" "$CONF" 2>/dev/null | head -n1 | tr -d "\"'"; }

# An existing install keeps its port.
if [ -f "$CONF" ]; then
  OLD_PORT=$(conf_val PORT)
  PORT=${OLD_PORT:-$PORT}
fi
case "$PORT" in ""|*[!0-9]*) echo "PORT must be a number."; exit 1 ;; esac

echo "==> Installing packages"
# sqlite is the sqlite3 command the nightly backup uses; the app needs only the py3-* packages.
apk add --no-cache python3 py3-flask py3-gunicorn py3-jwt py3-cryptography sqlite >/dev/null

[ -x "$INITD" ] && rc-service "$NAME" stop >/dev/null 2>&1 || true
if netstat -ltn 2>/dev/null | awk '{print $4}' | grep -q ":$PORT\$"; then
  echo "Port $PORT is already in use by something else. Re-run with STUBS_PORT=<free port>."; exit 1
fi

echo "==> Creating user and folders"
# BusyBox adduser -S puts a new user in "nogroup" unless told otherwise, so make the app's own group first.
grep -q "^$SVC_USER:" /etc/group || addgroup -S "$SVC_USER"
id "$SVC_USER" >/dev/null 2>&1 || adduser -S -D -H -h "$DATA_DIR" -s /sbin/nologin -G "$SVC_USER" "$SVC_USER"
mkdir -p "$APP_DIR" "$DATA_DIR/images" "$BACKUP_DIR"
chmod 700 "$BACKUP_DIR"

echo "==> Unpacking app to $APP_DIR"
TMP=$(mktemp -d /tmp/stubs-tmp.XXXXXX 2>/dev/null || mktemp -d)
sed -n '/^__PAYLOAD_BELOW__$/,$p' "$0" | tail -n +2 | base64 -d | ( cd "$TMP" && tar -xzf - )
rm -rf "$APP_DIR.new" && mv "$TMP/stubs" "$APP_DIR.new"
rm -rf "$APP_DIR.old"; [ -d "$APP_DIR" ] && mv "$APP_DIR" "$APP_DIR.old"
mv "$APP_DIR.new" "$APP_DIR"; rm -rf "$APP_DIR.old" "$TMP"
chown -R root:root "$APP_DIR"
chown -R "$SVC_USER:$SVC_USER" "$DATA_DIR"
chmod 750 "$DATA_DIR"

# ---------------------------------------------------------------- config
# OpenRC sources this file as shell, so values are single-quoted (TILE_URL holds braces).
add_setting() {  # add_setting FILE KEY VALUE COMMENT: only if KEY is not there yet
  grep -q "^$2=" "$1" 2>/dev/null && return 0
  case "$3" in *"'"*) echo "$2 may not contain a single quote."; exit 1 ;; esac
  printf "\n# %s\n%s='%s'\n" "$4" "$2" "$3" >> "$1"
  ADDED="${ADDED:-} $2"
}
[ -f "$CONF" ] || printf '# Stubs (concert history) settings. After editing: rc-service %s restart\n' "$NAME" > "$CONF"
add_setting "$CONF" PORT "$PORT" "Port gunicorn listens on. It binds 127.0.0.1 only: the Cloudflare tunnel is the way in."
add_setting "$CONF" DATA_DIR "$DATA_DIR" "Database and images (kept on upgrade)"
add_setting "$CONF" CF_TEAM_DOMAIN "" "Cloudflare Access team domain, e.g. yourteam.cloudflareaccess.com"
add_setting "$CONF" CF_AUD "" "AUD tag of the Access application on <your concerts host>/admin"
add_setting "$CONF" ADMIN_EMAILS "" "Emails that may edit through Access (comma separated); empty = nobody"
add_setting "$CONF" LAN_EDIT 1 "1 = a request not through Cloudflare, to one of LAN_HOSTS, may edit"
add_setting "$CONF" LAN_HOSTS "localhost,127.0.0.1" "Hosts (port ignored) that count as the LAN for LAN_EDIT"
add_setting "$CONF" PUBLIC_VIEW 1 "1 = anyone with the link can browse; 0 = everything needs an editor"
add_setting "$CONF" PUBLIC_POSTERS 0 "1 = posters are public too; 0 = editors only"
add_setting "$CONF" STUBS_API_KEY "" "Write key for scripts (X-API-Key or Authorization: Bearer); empty = none"
add_setting "$CONF" STUBS_READ_KEY "" "Read-only key for scripts; empty = none"
add_setting "$CONF" SETLISTFM_API_KEY "" "setlist.fm API key for the setlist panel; empty = panel lookups off"
add_setting "$CONF" GEOCODER_URL "https://nominatim.openstreetmap.org/search" "Nominatim search endpoint for venue coordinates"
add_setting "$CONF" TILE_URL "https://tile.openstreetmap.org/{z}/{x}/{y}.png" "Map tiles (this host is allowed in the CSP)"
# Holds API keys, so root only: OpenRC runs as root and exports what the service needs.
chmod 600 "$CONF"; chown root:root "$CONF"

# Health checks: add Stubs to HEALTH_CHECKS if the ops config exists.
add_health_check() {  # add_health_check "Name|url|service" service  (sets HC_ADDED / HC_MANUAL)
  [ -f "$OPS_CONF" ] || return 0
  grep -Eq "\|$2([^-A-Za-z0-9_]|\$)" "$OPS_CONF" && return 0
  if ! grep -q '^HEALTH_CHECKS=' "$OPS_CONF"; then
    printf '\n# Apps checked every 15 min (name|url|service); added by setup-stubs.sh\nHEALTH_CHECKS="%s"\n' "$1" >> "$OPS_CONF"
    HC_ADDED="${HC_ADDED:-} $2"
    return 0
  fi
  # append inside the existing (usually multi-line) HEALTH_CHECKS="..." value, before its closing quote
  awk -v add="$1" '
    !done && /^HEALTH_CHECKS="/ { inb = 1; if ($0 == "HEALTH_CHECKS=\"") { print; next } }
    inb && /"[ \t]*$/ { sub(/"[ \t]*$/, ""); print; print add "\""; inb = 0; done = 1; next }
    { print }' "$OPS_CONF" > "$OPS_CONF.new"
  if grep -Eq "\|$2([^-A-Za-z0-9_]|\$)" "$OPS_CONF.new" && sh -n "$OPS_CONF.new" 2>/dev/null; then
    cat "$OPS_CONF.new" > "$OPS_CONF"; HC_ADDED="${HC_ADDED:-} $2"
  else
    HC_MANUAL="${HC_MANUAL:-}
      $1"
  fi
  rm -f "$OPS_CONF.new"
}
add_health_check "Stubs|http://127.0.0.1:$PORT/healthz|stubs" stubs

# ---------------------------------------------------------------- service
cat > "$INITD" <<'EOF'
#!/sbin/openrc-run
name="stubs"
description="Stubs concert history (Flask + gunicorn, loopback only)"
: ${PORT:=8773}
: ${DATA_DIR:=/var/lib/stubs}
export HOME=/var/lib/stubs  # newer gunicorn keeps a small control socket under $HOME
export PORT DATA_DIR CF_TEAM_DOMAIN CF_AUD ADMIN_EMAILS LAN_EDIT LAN_HOSTS PUBLIC_VIEW PUBLIC_POSTERS STUBS_API_KEY STUBS_READ_KEY SETLISTFM_API_KEY GEOCODER_URL TILE_URL
supervisor="supervise-daemon"
respawn_delay=5
respawn_max=10
respawn_period=600
command="/usr/bin/gunicorn"
command_args="--preload --workers 2 --threads 4 --timeout 60 --bind 127.0.0.1:${PORT} --chdir /opt/stubs --access-logfile /var/log/stubs.log --error-logfile /var/log/stubs.log app:app"
command_user="stubs"
depend() { need net; after firewall; }
start_pre() { checkpath -f -o stubs:stubs -m 0640 /var/log/stubs.log; }
EOF
chmod 755 "$INITD"

echo "==> Installing the nightly backup"
mkdir -p /etc/periodic/daily
install -m 755 "$APP_DIR/ops/stubs-backup" "$BACKUP_JOB"
rc-update add crond default >/dev/null 2>&1 || true
rc-service crond start >/dev/null 2>&1 || true

echo "==> Starting the service"
rc-update add "$NAME" default >/dev/null 2>&1 || true
rc-service "$NAME" start
i=0
until wget -qO- "http://127.0.0.1:$PORT/healthz" 2>/dev/null | grep -q ok; do
  i=$((i + 1))
  if [ "$i" -ge 25 ]; then
    echo "The service did not answer. See $LOG:"; tail -n 20 "$LOG" 2>/dev/null || true
    exit 1
  fi
  sleep 1
done

echo "==> Taking a first backup"
"$BACKUP_JOB" || echo "    (backup reported a problem; see /var/log/stubs-backup.log)"

echo
echo "Stubs is running on 127.0.0.1:$PORT (loopback only)."
[ -n "${ADDED:-}" ] && echo "Settings added to $CONF:$ADDED"
[ -n "${HC_ADDED:-}" ] && echo "Added to HEALTH_CHECKS in $OPS_CONF:$HC_ADDED"
[ -n "${HC_MANUAL:-}" ] && echo "Couldn't edit HEALTH_CHECKS in $OPS_CONF; add these lines:$HC_MANUAL"
for k in CF_TEAM_DOMAIN CF_AUD ADMIN_EMAILS; do
  [ -n "$(conf_val "$k")" ] || echo "  - Set $k in $CONF (vim $CONF), then: rc-service $NAME restart"
done
echo "  - Tunnel: route your concerts hostname to http://127.0.0.1:$PORT"
echo "  - Cloudflare Access: an application on <your concerts host>/admin that lets in the emails in ADMIN_EMAILS"
echo "Config: $CONF   Data: $DATA_DIR   Backups: $BACKUP_DIR   Log: $LOG"
exit 0
